Here’s an example:

```typescript
function safeParse<T>(input: string): T {
    // Assume input is either a number or a string
    let result: T;
    if (typeof input === 'string') {
        result = input as T; // Explicitly assert that the string can be safely parsed to the desired type T
    } else if (typeof input === 'number') {
        result = input as T; // Or parse the number directly to the desired type T
    }
    return result;
}

// Usage:
const numOrStr = "42";
const numResult = safeParse<number>(numOrStr); // numResult is inferred as number
const strResult = safeParse<string>("hello"); // strResult is inferred as string
```

